def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n >= 98:
        return 'D'
    if history[0][1] == 'D':
        if history[-1][1] == 'D':
            return 'D'
        else:
            return 'C'
    else:
        opp_def = 0
        for _, o in history:
            if o == 'D':
                opp_def += 1
        if opp_def == 0:
            return 'D'
        else:
            if history[-1][1] == 'D':
                if n >= 2 and history[-1][0] == 'C' and history[-2][0] == 'C':
                    return 'D'
                else:
                    return 'C'
            else:
                return 'C'
